def count_returnable_rooms(n, s):
    # Helper function to check if a given room is returnable
    def is_returnable(start):
        position = start
        direction = 1 if s[position] == '>' else -1
        visited = set()
        for _ in range(n):
            if position in visited:
                return False
            visited.add(position)
            position = (position + direction) % n
            if s[position] == '<':
                direction = -1
            elif s[position] == '>':
                direction = 1
        return position == start

    returnable_count = 0
    for room in range(n):
        if is_returnable(room):
            returnable_count += 1

    return returnable_count

